using UnityEngine; public sealed class MusicController:MonoBehaviour { [SerializeField]private AudioSource source;public void Play(AudioClip clip,float volume){if(source==null)return;if(source.clip==clip&&source.isPlaying){source.volume=volume;return;}source.clip=clip;source.volume=volume;if(clip!=null)source.Play();else source.Stop();}public void SetVolume(float value){if(source!=null)source.volume=value;} }
